cd /home/admin1/projects/webhook-gateway && git rev-parse HEAD && docker compose ps api worker postgres && docker compose exec -T api node <<'JS'
(async()=>{
const pg=await import("pg");
const db=new pg.Client({connectionString:process.env.DATABASE_URL});
await db.connect();
const a=await db.query("SELECT d.destination_id,d.status,coalesce(d.last_status_code,0) code,count(*)::int n FROM deliveries d WHERE d.created_at>now()-interval '3 hours' GROUP BY 1,2,3 ORDER BY n DESC LIMIT 15");
console.log("DELIVERY_COUNTS",JSON.stringify(a.rows));
const b=await db.query("SELECT e.source_id,d.destination_id,d.status,d.last_status_code FROM events e JOIN deliveries d ON d.event_id=e.id WHERE e.received_at>now()-interval '3 hours' ORDER BY e.received_at DESC LIMIT 6");
console.log("LATEST",JSON.stringify(b.rows));
await db.end();
})().catch(e=>{console.log("DB_CHECK_FAILED",e.code||"ERR");process.exit(2)})
